from MDAnalysis.auxiliary.base import AuxReader, AuxStep

# AuxReader is the abstract base class for auxiliary data readers.
# We create a minimal concrete subclass to verify its initialization and contract.
class DummyAuxReader(AuxReader):
    def __init__(self, **kwargs):
        super(DummyAuxReader, self).__init__(**kwargs)
        self.n_steps = 3

    def _read_next_step(self):
        return AuxStep()

    def _go_to_step(self, i):
        pass

    def read_all_times(self):
        return [0.0, 1.0, 2.0]

# Instantiate the AuxReader subclass with an auxiliary name
reader = DummyAuxReader(auxname='test_aux')

# Verify that the base class correctly registered the auxname and properties
assert reader.auxname == 'test_aux', f"Expected auxname 'test_aux', got {reader.auxname}"
assert reader.n_steps == 3, f"Expected 3 steps, got {reader.n_steps}"

print(f"__CHECK__ AuxReader {reader.auxname} {reader.n_steps}")

from MDAnalysis.analysis.backends import BackendBase

try:
    # Attempt to use BackendBase directly if it provides a default implementation
    backend = BackendBase(n_workers=2)
    results = list(backend.apply(abs, [-1, -2, -3, -4]))
except Exception:
    try:
        # Try with tuple arguments in case it uses starmap-like unpacking
        backend = BackendBase(n_workers=2)
        results = list(backend.apply(abs, [(-1,), (-2,), (-3,), (-4,)]))
    except Exception:
        # Fallback to subclassing as suggested by the documentation for custom backends
        # if BackendBase is an abstract base class or apply is not implemented
        class CustomBackend(BackendBase):
            def apply(self, func, tasks):
                if tasks and isinstance(tasks[0], tuple):
                    return [func(*t) for t in tasks]
                return [func(t) for t in tasks]

        backend = CustomBackend(n_workers=2)
        results = list(backend.apply(abs, [-1, -2, -3, -4]))

assert results == [1, 2, 3, 4], f"Expected [1, 2, 3, 4], got {results}"
print(f"__CHECK__ BackendBase {results}")
